/**
 * Read-only access to FogRules (SRD 5.2.1 data generated by tools/build-srd-data.mjs,
 * plus any content packs registered through FogContentPacks).
 */
(function (global) {
  'use strict';

  function rules() {
    return global.FogRules;
  }

  function getClass(id) {
    return (id && rules().classes[id]) || null;
  }

  /** Every subclass of a class: the SRD one first, then any from content packs. */
  function listSubclasses(classId) {
    var cls = getClass(classId);
    if (!cls) return [];
    return [cls.subclass].concat(cls.extraSubclasses || []);
  }

  function getSubclass(classId, subclassId) {
    if (!subclassId) return null;
    return listSubclasses(classId).find(function (s) { return s.id === subclassId; }) || null;
  }

  function getSpecies(id) {
    return (id && id !== 'intro' && rules().species[id]) || null;
  }

  function getBackground(id) {
    return (id && id !== 'intro' && rules().backgrounds[id]) || null;
  }

  function getSpell(id) {
    return (id && rules().spells && rules().spells[id]) || null;
  }

  /**
   * Class features that may replace a Fighting Style feat (Paladin Blessed Warrior, Ranger Druidic Warrior).
   * They behave like a feat choice in that slot, so they are looked up like feats.
   */
  var altCache = null;
  function alternativeFeats() {
    if (altCache && altCache.rules === rules()) return altCache.map;
    var map = {};
    Object.keys(rules().classes).forEach(function (cid) {
      (rules().classes[cid].choices || []).forEach(function (ch) {
        if (!ch.alternative) return;
        var a = ch.alternative;
        map[a.id] = {
          id: a.id, name: a.name, description: a.description, category: 'fighting-style', alternative: true,
          classId: cid, cantripList: a.cantripList, cantripCount: a.count, spellAbility: a.ability,
        };
      });
    });
    altCache = { rules: rules(), map: map };
    return map;
  }

  function getFeat(id) {
    return (id && (rules().feats[id] || alternativeFeats()[id])) || null;
  }

  function getWeapon(id) {
    return (id && rules().weapons[id]) || null;
  }

  function getArmor(id) {
    return (id && rules().armor[id]) || null;
  }

  function getSkill(id) {
    return rules().skills.find(function (s) { return s.id === id; }) || null;
  }

  function getTool(id) {
    return rules().tools.find(function (t) { return t.id === id; }) || null;
  }

  function getLanguage(id) {
    var l = rules().languages;
    return l.standard.concat(l.rare).find(function (x) { return x.id === id; }) || null;
  }

  function getInvocation(id) {
    return (id && rules().invocations && rules().invocations[id]) || null;
  }

  function listInvocations() {
    return Object.values(rules().invocations || {});
  }

  function getMetamagic(id) {
    return (id && rules().metamagic && rules().metamagic[id]) || null;
  }

  function listMetamagic() {
    return Object.values(rules().metamagic || {});
  }

  function getGear(id) {
    return (id && rules().gear && rules().gear[id]) || null;
  }

  /** Adventuring gear by its name in an equipment list ("Explorer's Pack", "Pouches" → Pouch). */
  function gearByName(name) {
    if (!name || !rules().gear) return null;
    var clean = String(name).replace(/\s*\(.*\)$/, '').trim().toLowerCase();
    var all = Object.values(rules().gear);
    return all.find(function (g) { return g.name.toLowerCase() === clean; })
      || all.find(function (g) { return g.name.toLowerCase() === clean.replace(/(es|s)$/, ''); })
      || all.find(function (g) { return g.name.toLowerCase() === clean.replace(/s$/, ''); })
      || null;
  }

  function getGlossary(id) {
    return (id && rules().glossary && rules().glossary[id]) || null;
  }

  function listClasses() {
    return rules().meta.supportedClassIds.map(getClass);
  }

  function listSpecies() {
    return Object.keys(rules().species).filter(function (k) { return k !== 'intro'; }).map(getSpecies);
  }

  function listBackgrounds() {
    return Object.keys(rules().backgrounds).filter(function (k) { return k !== 'intro'; }).map(getBackground);
  }

  function listFeats(category) {
    return Object.values(rules().feats).filter(function (f) { return !category || f.category === category; });
  }

  function levelEntry(classId, level) {
    var cls = getClass(classId);
    return cls ? cls.levels[level] || null : null;
  }

  /** Proficiency bonus by character level (same for every class in the SRD tables). */
  function proficiencyBonus(level) {
    return Math.floor((level - 1) / 4) + 2;
  }

  function abilityModifier(score) {
    return Math.floor((score - 10) / 2);
  }

  function getSubclassLevel(classId) {
    var cls = getClass(classId);
    return cls ? cls.subclassLevel : 3;
  }

  /** Spell ids on a class's spell list at one spell level. */
  function spellIdsForList(listId, spellLevel) {
    var cls = getClass(listId);
    if (!cls || !cls.spellList) return [];
    return (cls.spellList[spellLevel] || []).slice();
  }

  /** Spell ids on any class's spell list at one spell level ("any class's spell list"). */
  function spellIdsAnyList(spellLevel) {
    return Object.values(rules().spells || {})
      .filter(function (s) { return s.level === spellLevel && s.classes && s.classes.length; })
      .map(function (s) { return s.id; });
  }

  function spellsForClass(classId, spellLevel) {
    return spellIdsForList(classId, spellLevel).map(getSpell).filter(Boolean);
  }

  function isSpellcaster(classId) {
    var cls = getClass(classId);
    return !!(cls && cls.spellcasting);
  }

  /**
   * Spell slots of a class at a level as an array of 9 counts.
   * Pact Magic (Warlock) slots all share one level, so they appear at that level only.
   */
  function slotsAt(classId, level) {
    var entry = levelEntry(classId, level);
    if (!entry) return [0, 0, 0, 0, 0, 0, 0, 0, 0];
    if (entry.pactSlots) {
      var out = [0, 0, 0, 0, 0, 0, 0, 0, 0];
      out[entry.pactSlotLevel - 1] = entry.pactSlots;
      return out;
    }
    return (entry.slots || [0, 0, 0, 0, 0, 0, 0, 0, 0]).slice();
  }

  /** Highest spell level for which a class has slots at a level (0 when none). */
  function maxSpellLevel(classId, level) {
    var max = 0;
    slotsAt(classId, level).forEach(function (n, i) { if (n > 0) max = i + 1; });
    return max;
  }

  function hasFeature(classId, level, featureName) {
    var cls = getClass(classId);
    if (!cls) return false;
    return cls.features.some(function (f) { return f.name === featureName && f.level <= level; });
  }

  global.FogRulesApi = {
    rules: rules,
    getClass: getClass,
    listSubclasses: listSubclasses,
    getSubclass: getSubclass,
    getSpecies: getSpecies,
    getBackground: getBackground,
    getSpell: getSpell,
    getFeat: getFeat,
    alternativeFeats: alternativeFeats,
    getWeapon: getWeapon,
    getArmor: getArmor,
    getSkill: getSkill,
    getTool: getTool,
    getLanguage: getLanguage,
    getInvocation: getInvocation,
    listInvocations: listInvocations,
    getMetamagic: getMetamagic,
    listMetamagic: listMetamagic,
    getGear: getGear,
    gearByName: gearByName,
    getGlossary: getGlossary,
    listClasses: listClasses,
    listSpecies: listSpecies,
    listBackgrounds: listBackgrounds,
    listFeats: listFeats,
    levelEntry: levelEntry,
    proficiencyBonus: proficiencyBonus,
    abilityModifier: abilityModifier,
    getSubclassLevel: getSubclassLevel,
    spellIdsForList: spellIdsForList,
    spellIdsAnyList: spellIdsAnyList,
    spellsForClass: spellsForClass,
    isSpellcaster: isSpellcaster,
    slotsAt: slotsAt,
    maxSpellLevel: maxSpellLevel,
    hasFeature: hasFeature,
  };
})(window);
